  final String? tableId;
  final String? text;
  /// A chart's scale marks, from its foot to its top.
  final List<PageBlockTicksItem>? ticks;
  final String? title;
  final String? tone;
  final String type;
  /// In place of a part over Taskiem's own records, why it is not drawn for
